 ///
 /// # Description
 ///
 /// A memory region.
 ///
 #[verus_verify(external_derive)]
 #[derive(Debug, Clone)]
 pub struct MemoryRegion<T: Address> {
     name: String,
     start: T,
     size: usize,
     typ: MemoryRegionType,
     perm: AccessPermission,
     cache_policy: Option<MmioCachePolicy>,
 }

 impl<T: Address> MemoryRegion<T> {
     /// Maximum byte-length of a memory region name.
     const MEMORY_REGION_NAME_MAX: usize = 32;

     /// Creates a new memory region.
     pub fn new(
         name: &str,
         start: T,
         size: usize,
         typ: MemoryRegionType,
         perm: AccessPermission,
     ) -> Result<Self, Error> {
         // Check if name is too long (byte length).
         if name.len() > Self::MEMORY_REGION_NAME_MAX {
             let reason: &str = "memory region name is too long";
             error!("{reason} (name.len={}, NAME_MAX={})", name.len(), Self::MEMORY_REGION_NAME_MAX);
             return Err(Error::new(ErrorCode::InvalidArgument, reason));
         }

         // Check if size of the memory region is valid.
         if size == 0 {
             return Err(Error::new(ErrorCode::InvalidArgument, "invalid memory region size"));
         }

         // Check if memory region is too big.
         let start_raw_addr: usize = start.clone().into_raw_value();
         let end_raw_addr: usize = match start_raw_addr.checked_add(size - 1) {
             Some(end_raw_addr) => end_raw_addr,
             None => {
                 return Err(Error::new(ErrorCode::TooBig, "memory region is too big"));
             },
         };

         // Check if memory region spans outside the address space.
         if end_raw_addr > T::max_addr() {
             return Err(Error::new(
                 ErrorCode::InvalidArgument,
                 "memory region spans outside the address space",
             ));
         }

         Ok(Self {
             name: name.to_string(),
             start,
             size,
             typ,
             perm,
             cache_policy: None,
         })
     }

     pub fn name(&self) -> String {
         self.name.clone()
     }

     /// Returns the first valid address that lies in the target memory region.
     #[verus_spec(result =>
         ensures
             // Faithful read: the returned address has the same abstract address
             // as the stored `start` (`spec_addr(&result) == self@.start`). `T` is
             // a bare `Address` (no `View` bound), so the value is projected
             // through the universal `spec_addr`, not `result@`. `Address: Copy`,
             // so the field read is identity (`result == self.start`), which
             // discharges the postcondition by congruence of `spec_addr`.
             crate::hal::mem::spec_addr(&result) == self@.start,
     )]
     pub fn start(&self) -> T {
         // VERUS REWRITE: original exec body was `self.start.clone()`.
         // Verus limitation: `Clone::clone` on a generic `T: Address` has no spec
         // relating `spec_addr(&result)` to `spec_addr(&self.start)`, so the
         // postcondition `spec_addr(&result) == self@.start` cannot be discharged
         // through `.clone()`. Minimal reproducer — restoring `self.start.clone()`:
         //   error: postcondition not satisfied
         //     --> region.rs:218:13  (spec_addr(&result) == self@.start)
         //     221 | self.start.clone()  -- at the end of the function body
         //   verification results:: 40 verified, 1 errors
         // `Address: Copy` (sys/mm/address/mod.rs:33) makes the direct field read
         // identity (`result == self.start`), discharging the postcondition.
         // Semantically equivalent: clone of a `Copy` type is a bitwise copy.
         self.start
     }

     /// Returns the size of the target memory region.
     #[verus_spec(result =>
         ensures
             result as int == self@.size,
     )]
     pub fn size(&self) -> usize {
         self.size
     }

     /// Returns the type of the target memory region.
     pub fn typ(&self) -> MemoryRegionType {
         self.typ
     }

     /// Returns the permissions of the target memory region.
     pub fn perm(&self) -> AccessPermission {
         self.perm
     }

     ///
     /// # Description
     ///
     /// Returns the MMIO cache policy of the target memory region, if set.
     ///
     /// # Returns
     ///
     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
     ///
     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
         self.cache_policy
     }

     ///
     /// # Description
     ///
     /// Sets the MMIO cache policy of the target memory region.
     ///
     /// # Parameters
     ///
     /// - `policy`: The cache policy to assign.
     ///
     pub fn set_cache_policy(&mut self, policy: MmioCachePolicy) {
         self.cache_policy = Some(policy);
     }
