     type V = MemoryRegionView;

     closed spec fn view(&self) -> MemoryRegionView {
         MemoryRegionView {
             start: spec_addr(&self.start),
             size: self.size as int,
             typ: self.typ,
             perm: self.perm,
             cache_policy: self.cache_policy,
